    /**
     * Advanced builder for endpoint for the MTConnect component.
     */
    public interface AdvancedMTConnectEndpointBuilder
            extends
                AdvancedMTConnectEndpointConsumerBuilder,
                AdvancedMTConnectEndpointProducerBuilder {
        default MTConnectEndpointBuilder basic() {
            return (MTConnectEndpointBuilder) this;
        }

        /**
         * An MTConnect XPath filter the agent applies to the current and sample
         * requests, passed unchanged, such as //Axes//Linear to receive the
         * linear axes only.
         * 
         * The option is a: <code>java.lang.String</code> type.
         * 
         * Group: common (advanced)
         * 
         * @param path the value to set
         * @return the dsl builder
         */
        default AdvancedMTConnectEndpointBuilder path(String path) {
            doSetProperty("path", path);
            return this;
        }
    }

    public interface MTConnectBuilders {
        /**
         * MTConnect (camel-mtconnect)
         * Receive the observations of an MTConnect agent through its streaming
         * sample request or by polling it, one message per observation, or send
         * the probe, current, sample and asset requests on demand.
         * 
         * Category: iot
         * Since: 4.24
         * Maven coordinates: org.apache.camel:camel-mtconnect
         * 
         * @return the dsl builder for the headers' name.
         */
        default MTConnectHeaderNameBuilder mtconnect() {
            return MTConnectHeaderNameBuilder.INSTANCE;
        }
        /**
         * MTConnect (camel-mtconnect)
         * Receive the observations of an MTConnect agent through its streaming
         * sample request or by polling it, one message per observation, or send
         * the probe, current, sample and asset requests on demand.
         * 
         * Category: iot
         * Since: 4.24
         * Maven coordinates: org.apache.camel:camel-mtconnect
         * 
         * Syntax: <code>mtconnect:agentUrl</code>
         * 
         * Path parameter: agentUrl (required)
         * The agent address: http or https, host, port and an optional base
         * path, such as http://agent:5000.
         * 
         * @param path agentUrl
         * @return the dsl builder
         */
        default MTConnectEndpointBuilder mtconnect(String path) {
            return MTConnectEndpointBuilderFactory.endpointBuilder("mtconnect", path);
        }
        /**
         * MTConnect (camel-mtconnect)
         * Receive the observations of an MTConnect agent through its streaming
         * sample request or by polling it, one message per observation, or send
         * the probe, current, sample and asset requests on demand.
         * 
         * Category: iot
         * Since: 4.24
         * Maven coordinates: org.apache.camel:camel-mtconnect
         * 
         * Syntax: <code>mtconnect:agentUrl</code>
         * 
         * Path parameter: agentUrl (required)
         * The agent address: http or https, host, port and an optional base
         * path, such as http://agent:5000.
         * 
         * @param componentName to use a custom component name for the endpoint
         * instead of the default name
         * @param path agentUrl
         * @return the dsl builder
         */
        default MTConnectEndpointBuilder mtconnect(String componentName, String path) {
            return MTConnectEndpointBuilderFactory.endpointBuilder(componentName, path);
        }

    }
