    static MTConnectEndpointBuilder endpointBuilder(String componentName, String path) {
        class MTConnectEndpointBuilderImpl extends AbstractEndpointBuilder implements MTConnectEndpointBuilder, AdvancedMTConnectEndpointBuilder {
            public MTConnectEndpointBuilderImpl(String path) {
                super(componentName, path);
            }
        }
        return new MTConnectEndpointBuilderImpl(path);
    }
